def biggest_move(path):
    closes = []
    # read the file at path into closes
    with open(path) as f:
        lines = f.read().splitlines()
    for line in lines[1:]:
        if line.strip() == "":
            continue
        date, close = line.split(",")
        closes.append(float(close))
    best = 0.0
    # compare each close with the one before it
    for i in range(1, len(closes)):
        move = abs(closes[i] - closes[i - 1])
        if move > best:
            best = move
    return round(best, 2)

explain.text:
Skip line 0, the header, and any empty line. Split each row at the comma and keep the close as a float. `abs` makes a fall count as a move.

